Subroutine Average(a As Integer, b As Integer) As Real
  Return (a + b) / 2;
EndSubroutine

Subroutine Status(average As Real) As String
  If average >= 6 Then
    Return "passed";
  EndIf
  Return "failed";
EndSubroutine

Algorithm ReportCard
  Define name As String;
  Define m1, m2 As Integer;
  Define bestName As String <- "";
  Define bestAverage As Real <- -1.0;
  For i <- 1 To 3 Do
    Read name;
    Read m1;
    Read m2;
    Define avg As Real <- Average(m1, m2);
    Write name, ": ", avg, " ", Status(avg);
    If avg > bestAverage Then
      bestAverage <- avg;
      bestName <- name;
    EndIf
  EndFor
  Write "Best average: ", bestName;
EndAlgorithm
